function nextPermutation(values) {
  const a = [...values];
  let pivot = a.length - 2;
  while (pivot >= 0 && a[pivot] >= a[pivot + 1]) {
    pivot--;
  }
  if (pivot < 0) return null;
  let next = a.length - 1;
  while (a[next] <= a[pivot]) next--;
  [a[pivot], a[next]] = [a[next], a[pivot]];
  for (let left = pivot + 1, right = a.length - 1;
       left < right; left++, right--) {
    [a[left], a[right]] = [a[right], a[left]];
  }
  return a;
}

function* permutations(n) {
  let current = Array.from({length: n}, (_, i) => i + 1);
  while (current !== null) {
    yield current.slice();
    current = nextPermutation(current);
  }
}

function nextBits(bits) {
  const b = [...bits];
  let i = b.length - 1;
  while (i >= 0 && b[i] === 1) {
    b[i] = 0;
    i--;
  }
  if (i < 0) return null;
  b[i] = 1;
  return b;
}

function nextCombination(values, n) {
  const a = [...values];
  const r = a.length;
  let i = r - 1;
  while (i >= 0 && a[i] === n - r + i + 1) {
    i--;
  }
  if (i < 0) return null;
  a[i]++;
  for (let j = i + 1; j < r; j++) {
    a[j] = a[j - 1] + 1;
  }
  return a;
}
